package com.bank.search.repository;

import com.bank.search.model.Transaction;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import java.util.List;

public interface TransactionSearchRepository extends JpaRepository<Transaction, Long> {

    // Full-text search: @@ matches the query against the GIN-indexed tsvector,
    // ts_rank orders by relevance. Stemming means 'rent' also matches 'rental'.
    @Query(value =
        "SELECT * FROM transactions t, to_tsquery('english', :term) q " +
        "WHERE t.search_vector @@ q " +
        "ORDER BY ts_rank(t.search_vector, q) DESC",
        nativeQuery = true)
    List<Transaction> search(@Param("term") String term);
}
