package com.bank.search.service;

import com.bank.search.model.Transaction;
import com.bank.search.repository.TransactionSearchRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.util.List;

@Service
public class TransactionSearchService {
    private static final Logger log = LoggerFactory.getLogger(TransactionSearchService.class);
    private final TransactionSearchRepository repo;

    public TransactionSearchService(TransactionSearchRepository repo) { this.repo = repo; }

    // Accepts a user word; to_tsquery handles stemming and the GIN index does the lookup.
    public List<Transaction> search(String term) {
        // sanitize into a single lexeme query (production: use plainto_tsquery / websearch_to_tsquery)
        String tsTerm = term.trim().replaceAll("\\s+", " & ");
        List<Transaction> hits = repo.search(tsTerm);
        log.info("Full-text search '{}' matched {} rows via GIN index", term, hits.size());
        return hits;
    }
}
